#include <Arduino.h>
const uint8_t SSR=8; const unsigned long TS_MS=100, WINDOW_MS=2000;
float SP=50,Kp=6,Ki=.08,Kd=8,I=0,ePrev=0; float TEMP_OFFSET=0,TEMP_SCALE=20,TEMP_MAX=70; bool runCtl=false;
unsigned long lastCtl=0,windowStart=0;
void setKV(String s){int c=s.indexOf(',');if(c<0)return;String k=s.substring(0,c),v=s.substring(c+1);float x=v.toFloat();if(k=="SP")SP=x;else if(k=="KP")Kp=x;else if(k=="KI")Ki=x;else if(k=="KD")Kd=x;else if(k=="RUN")runCtl=(x>0.5);else if(k=="ZEROI")I=0;}
void setup(){Serial.begin(115200);pinMode(SSR,OUTPUT);digitalWrite(SSR,LOW);windowStart=millis();Serial.println("ms,temp_C,sp_C,error,P,I,D,pid_pct,ssr");}
void loop(){if(Serial.available()){String s=Serial.readStringUntil('\n');s.trim();setKV(s);}unsigned long now=millis();if(now-lastCtl<TS_MS)return;float dt=(now-lastCtl)/1000.0f;lastCtl=now;int adc=analogRead(A0);float V=adc*5.0f/1023.0f,T=TEMP_OFFSET+TEMP_SCALE*V;bool valid=isfinite(T)&&T>=0&&T<=TEMP_MAX;if(!valid){runCtl=false;digitalWrite(SSR,LOW);}float e=SP-T,P=Kp*e,D=Kd*(e-ePrev)/max(dt,.001f),trial=P+I+D,u=constrain(trial,0.0f,100.0f);if(runCtl&&!((u>=100&&e>0)||(u<=0&&e<0)))I+=Ki*e*dt;I=constrain(I,0.0f,100.0f);u=constrain(P+I+D,0.0f,100.0f);ePrev=e;if(now-windowStart>=WINDOW_MS)windowStart=now;bool on=runCtl&&valid&&((now-windowStart)<(unsigned long)(WINDOW_MS*u/100.0f));digitalWrite(SSR,on);Serial.print(now);Serial.print(',');Serial.print(T,3);Serial.print(',');Serial.print(SP,3);Serial.print(',');Serial.print(e,3);Serial.print(',');Serial.print(P,3);Serial.print(',');Serial.print(I,3);Serial.print(',');Serial.print(D,3);Serial.print(',');Serial.print(u,3);Serial.print(',');Serial.println(on?1:0);}
